const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://oldmatecranes.com.au/'
};

const menu = {
  link1:{
    copy:'home',
    url: 'http://oldmatecranes.com.au/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};



const Menu = () => {
  return (
    <>
      <section>
      <nav class="navbar navbar-default mainbar" role="navigation">
          <div class="navbar-header">
              <button type="button" class="navbar-toggle hvr-bounce-to-bottom collapsed" data-toggle="collapse" data-target="#my-navbar-collapse">
                <span class="sr-only">Toggle navigation</span>
                <span class="icon-bar"></span>
                <span class="icon-bar"></span>
                <span class="icon-bar"></span>
              </button>
          </div>

          <div class="collapse navbar-collapse" id="my-navbar-collapse">
            <ul class="nav navbar-nav">
              <li><a data-toggle="collapse" data-target=".navbar-collapse" href="#link1" class="navelement">Link 1</a></li>

              <li><a data-toggle="collapse" data-target=".navbar-collapse" href="#link2" class="navelement">Link 2</a></li>

            </ul>
          </div>
      </nav>
        <div className='offcanvas offcanvas-end bg-red' tabIndex='-1' id='offcanvasRight' aria-labelledby='offcanvasRightLabel'>
          <div className='offcanvas-header'>
            <button type='button' className='btn-close' data-bs-dismiss='offcanvas' aria-label='Close'></button>
          </div>
          <div className='offcanvas-body menu-links'>
            <a href={menu.link1.url}>{menu.link1.copy}</a><br/>
            <a href={menu.link2.url}>{menu.link2.copy}</a><br/>
            <a href={menu.link3.url}>{menu.link3.copy}</a><br/>
            <a href={menu.link4.url}>{menu.link4.copy}</a><br/>
            <a href={menu.link5.url}>{menu.link5.copy}</a><br/>
            <a href={menu.link6.url}>{menu.link6.copy}</a><br/>
            <a href={menu.link7.url}>{menu.link7.copy}</a>
          </div>
        </div>
      </section>
    </>
  )
}

export default Menu;
